/**
 * Repository interface (TZ §8). Everything above this layer is storage-agnostic:
 * `PrismaRepository` (PostgreSQL 16) is used in production, `MemoryRepository`
 * in unit tests and for a zero-dependency dev mode. Both are checked by the
 * same contract suite (src/repo/repo.contract.ts).
 *
 * Conventions:
 *  - ids are UUID v7 generated by the app (`newId()`), so `id` order = creation order;
 *  - lists are cursor-paginated: the cursor is the opaque last sort value;
 *  - optimistic locking: `version` integers; a stale write returns 'version_mismatch';
 *  - soft delete: `deletedAt`; physical erase after 30 days via `purgeDeleted`.
 */
import type {
  Concept,
  ContentPackage,
  ContentStatus,
  Course,
  GlossaryTerm,
  I18nStatus,
  Item,
  ItemResponse,
  Lang,
  Manifest,
  Objective,
  Process,
  Subject,
  SubjectGroup,
  Textbook,
  Topic,
  Unit,
} from '@bilig/content-model';
import type { AuthorSubrole, Permission, Role, Scope } from '@bilig/permissions';

export type Id = string;

export interface PageReq {
  cursor?: string;
  limit: number;
}
export interface PageRes<T> {
  items: T[];
  nextCursor: string | null;
}

export type WriteResult<T> = T | 'not_found' | 'version_mismatch';
export type DeleteResult = 'ok' | 'not_found' | 'version_mismatch';

// ---------------------------------------------------------------------------
// Identity & schools
// ---------------------------------------------------------------------------

export type UserKind = 'adult' | 'student';
export type UserStatus = 'active' | 'blocked' | 'invited' | 'pending';

export interface UserRec {
  id: Id;
  kind: UserKind;
  /** Lower-cased. Students never have one (TZ §6 minimisation). */
  email: string | null;
  emailVerifiedAt: Date | null;
  displayName: string;
  locale: Lang;
  status: UserStatus;
  createdAt: Date;
  updatedAt: Date;
  deletedAt: Date | null;
  /** v0.6.0: pending self-registration details (null once provisioned / when absent). */
  signup?: SignupRec | null;
  /** v0.7.0: WhatsApp number in E.164 (`+996XXXXXXXXX`), unique; repos return null when unset. */
  phone?: string | null;
  /** v0.7.0: when a one-time code proved the number; repos return null when unset. */
  phoneVerifiedAt?: Date | null;
  /** v0.8.0: the language the teacher teaches in; repos return null when unset. */
  teachingLang?: TeachingLang | null;
  /** v0.8.0: the last successful sign-in; repos return null when unset. */
  lastLoginAt?: Date | null;
}

export type TeachingLang = 'ky' | 'ru' | 'uz' | 'en';

/** v0.6.0: what a teacher entered at sign-up, kept until the e-mail is confirmed. */
export interface SignupRec {
  teaching?: { subjects: string[]; grades: number[] };
  schoolName?: string;
  region?: string;
}

export type CredentialType = 'password' | 'pin' | 'google' | 'totp';
export interface CredentialRec {
  userId: Id;
  type: CredentialType;
  /** argon2id hash (password, pin) or the TOTP secret (base32, `pending:` prefix until verified). */
  secretHash: string;
  failedCount: number;
  lockedUntil: Date | null;
  updatedAt: Date;
}

export type Audience = 'client' | 'admin';
export interface SessionRec {
  id: Id;
  userId: Id;
  /** sha256 of the refresh token. */
  refreshHash: string;
  /** All rotations of one login share a family; reuse revokes the family. */
  family: Id;
  audience: Audience;
  device: string;
  ip: string | null;
  createdAt: Date;
  expiresAt: Date;
  revokedAt: Date | null;
  /** Set when this token was rotated (its successor id). */
  replacedById: Id | null;
}

export interface GrantRec {
  userId: Id;
  role: Role;
  scope: Scope;
  scopeId: string | null;
  subrole: AuthorSubrole | null;
}

export type AuthTokenPurpose = 'email_verify' | 'password_reset' | 'totp_enroll' | 'email_code';
export interface AuthTokenRec {
  id: Id;
  userId: Id;
  purpose: AuthTokenPurpose;
  tokenHash: string;
  expiresAt: Date;
  usedAt: Date | null;
  /** v0.6.0: wrong tries (e-mail codes); 0 when absent. */
  attempts?: number;
}

/** v0.7.0: what a phone one-time code / token is for. */
export type PhoneOtpPurpose = 'register' | 'reset';
/**
 * v0.7.0: a phone-keyed one-time secret. `code` rows hold the 6-digit code sent
 * to WhatsApp (hash bound to the row id); `token` rows the opaque token a
 * verified code is exchanged for (sha256). No user: a registration has none yet.
 */
export interface PhoneOtpRec {
  id: Id;
  /** E.164. */
  phone: string;
  purpose: PhoneOtpPurpose;
  kind: 'code' | 'token';
  hash: string;
  /** The language the start request asked for (messages, the new account). */
  locale: Lang;
  attempts: number;
  createdAt: Date;
  expiresAt: Date;
  usedAt: Date | null;
}

export interface InviteRec {
  id: Id;
  email: string;
  role: Role;
  scope: Scope;
  scopeId: string | null;
  subrole: AuthorSubrole | null;
  /** v0.8.0: the permissions ticked for a manager invite (empty otherwise; repos return [] when unset). */
  permissions?: Permission[];
  tokenHash: string;
  invitedBy: Id;
  createdAt: Date;
  expiresAt: Date;
  acceptedAt: Date | null;
  revokedAt: Date | null;
}

export interface SchoolRec {
  id: Id;
  name: string;
  region: string;
  type: 'state' | 'private';
  language: Lang;
  status: 'active' | 'suspended';
  /** v0.6.0: `self` = a self-registered teacher's personal school; repos return 'admin' by default. */
  origin?: SchoolOrigin;
  createdAt: Date;
  /** Optimistic version (starts at 1). */
  version: number;
}
export type SchoolOrigin = 'admin' | 'self';

export interface LicenseRec {
  id: Id;
  schoolId: Id;
  subjects: string[];
  grades: number[];
  seats: number;
  startsAt: Date;
  endsAt: Date;
  /** Optimistic version (starts at 1). */
  version: number;
}

export interface ClassRec {
  id: Id;
  schoolId: Id;
  name: string;
  grade: number;
  joinCode: string;
  joinCodeEnabled: boolean;
  /** v0.6.0: subject taught in the class (= subjectKeys[0]); repos return null when unset. */
  subjectKey?: string | null;
  /** v0.8.0: every subject taught in the class; repos return [] when unset. */
  subjectKeys?: string[];
  createdBy: Id;
  createdAt: Date;
  deletedAt: Date | null;
}

export interface EnrollmentRec {
  classId: Id;
  userId: Id;
  role: 'student' | 'teacher';
  createdAt: Date;
}

export interface ConsentRec {
  studentId: Id;
  schoolId: Id;
  confirmedBy: Id;
  confirmedAt: Date;
}

