// ---------------------------------------------------------------------------
// The repository
// ---------------------------------------------------------------------------

export interface UserFilter {
  q?: string;
  ids?: Id[];
  status?: UserStatus;
}

export interface Repository {
  readonly kind: 'memory' | 'prisma';
  ping(): Promise<boolean>;
  close(): Promise<void>;

  // identity
  createUser(u: Omit<UserRec, 'createdAt' | 'updatedAt' | 'deletedAt'>): Promise<UserRec | 'conflict'>;
  getUser(id: Id): Promise<UserRec | null>;
  getUserByEmail(email: string): Promise<UserRec | null>;
  /** v0.7.0: by the E.164 number (exact match). */
  getUserByPhone(phone: string): Promise<UserRec | null>;
  updateUser(
    id: Id,
    patch: Partial<Pick<UserRec, 'displayName' | 'locale' | 'status' | 'emailVerifiedAt' | 'deletedAt' | 'signup' | 'phone' | 'phoneVerifiedAt' | 'teachingLang' | 'lastLoginAt'>>,
  ): Promise<UserRec | null>;
  listUsers(filter: UserFilter, page: PageReq): Promise<PageRes<UserRec>>;
  getUsers(ids: readonly Id[]): Promise<UserRec[]>;

  getCredential(userId: Id, type: CredentialType): Promise<CredentialRec | null>;
  setCredential(userId: Id, type: CredentialType, secretHash: string): Promise<void>;
  updateCredential(userId: Id, type: CredentialType, patch: Partial<Pick<CredentialRec, 'failedCount' | 'lockedUntil'>>): Promise<void>;
  deleteCredential(userId: Id, type: CredentialType): Promise<void>;

  listGrants(userId: Id): Promise<GrantRec[]>;
  listGrantsByScope(scope: Scope, scopeId: string): Promise<GrantRec[]>;
  setGrants(userId: Id, grants: Omit<GrantRec, 'userId'>[]): Promise<void>;
  addGrant(grant: GrantRec): Promise<void>;

  createSession(s: SessionRec): Promise<void>;
  getSession(id: Id): Promise<SessionRec | null>;
  getSessionByRefreshHash(hash: string): Promise<SessionRec | null>;
  /**
   * Atomic rotation: marks `oldId` revoked+replaced and inserts `next` only if
   * `oldId` was still active. Returns false when it was already rotated/revoked
   * (a concurrent refresh or a replay).
   */
  rotateSession(oldId: Id, next: SessionRec, at: Date): Promise<boolean>;
  revokeSession(id: Id, at: Date): Promise<void>;
  revokeFamily(family: Id, at: Date): Promise<number>;
  revokeUserSessions(userId: Id, at: Date): Promise<number>;
  listActiveSessions(userId: Id, now: Date): Promise<SessionRec[]>;

  createAuthToken(t: AuthTokenRec): Promise<void>;
  /** Marks the token used and returns it, or null if unknown/expired/used. */
  consumeAuthToken(tokenHash: string, purpose: AuthTokenPurpose, now: Date): Promise<AuthTokenRec | null>;
  /** The token when it exists, is unexpired and unused — without consuming it. */
  findAuthToken(tokenHash: string, purpose: AuthTokenPurpose, now: Date): Promise<AuthTokenRec | null>;
  /** v0.6.0: the user's most recently issued token of this purpose (any state; latest `expiresAt`). */
  latestAuthToken(userId: Id, purpose: AuthTokenPurpose): Promise<AuthTokenRec | null>;
  /** v0.6.0: marks every unused token of this purpose used (a new code invalidates the old). Returns the count. */
  revokeAuthTokens(userId: Id, purpose: AuthTokenPurpose, now: Date): Promise<number>;
  /**
   * v0.6.0: atomically counts one wrong try against an unused token; at `max`
   * the token is burned (marked used). Returns the new attempt count (0 when unknown/used).
   */
  failAuthTokenAttempt(id: Id, max: number, now: Date): Promise<number>;

  // v0.7.0: phone one-time codes and tokens
  createPhoneOtp(o: PhoneOtpRec): Promise<void>;
  /** The most recently issued row for the number, purpose and kind (any state; latest `createdAt`, then id). */
  latestPhoneOtp(phone: string, purpose: PhoneOtpPurpose, kind: PhoneOtpRec['kind']): Promise<PhoneOtpRec | null>;
  /** Marks every unused row of the number, purpose and kind used. Returns the count. */
  revokePhoneOtps(phone: string, purpose: PhoneOtpPurpose, kind: PhoneOtpRec['kind'], now: Date): Promise<number>;
  /** Atomically counts a wrong try against an unused row; burns it (marks used) at `max`. Returns the new count (0 when unknown/used). */
  failPhoneOtpAttempt(id: Id, max: number, now: Date): Promise<number>;
  /** The row with this hash and kind when it is unexpired and unused — without consuming it. */
  findPhoneOtp(hash: string, kind: PhoneOtpRec['kind'], now: Date): Promise<PhoneOtpRec | null>;
  /** Marks the row with this hash and kind used and returns it, or null if unknown/expired/used. */
  consumePhoneOtp(hash: string, kind: PhoneOtpRec['kind'], now: Date): Promise<PhoneOtpRec | null>;

  createInvite(i: Omit<InviteRec, 'revokedAt'> & { revokedAt?: Date | null }): Promise<void>;
  getInvite(id: Id): Promise<InviteRec | null>;
  getInviteByHash(tokenHash: string): Promise<InviteRec | null>;
  updateInvite(id: Id, patch: Partial<Pick<InviteRec, 'tokenHash' | 'expiresAt' | 'revokedAt'>>): Promise<InviteRec | null>;
  /** False when unknown, already accepted or revoked. */
  markInviteAccepted(id: Id, at: Date): Promise<boolean>;
  listInvites(filter: { scope?: Scope; scopeIds?: string[] }, page: PageReq): Promise<PageRes<InviteRec>>;

  createSchool(s: Omit<SchoolRec, 'version'> & { version?: number }): Promise<void>;
  getSchool(id: Id): Promise<SchoolRec | null>;
  /** Bumps `version`. `expectedVersion` (optional) → 'version_mismatch' when stale. */
  updateSchool(id: Id, patch: Partial<Omit<SchoolRec, 'id' | 'createdAt' | 'version'>>, expectedVersion?: number | null): Promise<SchoolRec | null | 'version_mismatch'>;
  listSchools(filter: { ids?: Id[] }, page: PageReq): Promise<PageRes<SchoolRec>>;

  createLicense(l: Omit<LicenseRec, 'version'> & { version?: number }): Promise<LicenseRec | 'conflict'>;
  getLicense(id: Id): Promise<LicenseRec | null>;
  updateLicense(id: Id, patch: Partial<Omit<LicenseRec, 'id' | 'schoolId' | 'version'>>, expectedVersion?: number | null): Promise<LicenseRec | null | 'version_mismatch'>;
  deleteLicense(id: Id, expectedVersion?: number | null): Promise<boolean | 'version_mismatch'>;
  listLicenses(filter: { schoolIds?: Id[] }, page: PageReq): Promise<PageRes<LicenseRec>>;

  createClass(c: ClassRec): Promise<ClassRec | 'conflict'>;
  getClass(id: Id): Promise<ClassRec | null>;
  getClassByJoinCode(code: string): Promise<ClassRec | null>;
  /** v0.8.0: `subjectKeys` wins over `subjectKey`; the repos keep subjectKey = subjectKeys[0]. */
  updateClass(id: Id, patch: Partial<Pick<ClassRec, 'name' | 'grade' | 'joinCode' | 'joinCodeEnabled' | 'deletedAt' | 'subjectKey' | 'subjectKeys'>>): Promise<ClassRec | null | 'conflict'>;
  listClasses(filter: { ids?: Id[]; schoolIds?: Id[] }, page: PageReq): Promise<PageRes<ClassRec>>;

  addEnrollment(e: Omit<EnrollmentRec, 'createdAt'>): Promise<void>;
  removeEnrollment(classId: Id, userId: Id): Promise<void>;
  listEnrollments(filter: { classId?: Id; classIds?: Id[]; userId?: Id; role?: 'student' | 'teacher' }): Promise<EnrollmentRec[]>;

  setConsent(c: ConsentRec | { studentId: Id; remove: true }): Promise<void>;
  listConsents(studentIds: readonly Id[]): Promise<ConsentRec[]>;

  // content
  content<K extends ContentKind>(kind: K): ContentStore<ContentKinds[K]>;

  createTopic(t: Omit<TopicRec, 'createdAt' | 'updatedAt' | 'deletedAt' | 'version' | 'updatedBy'> & { updatedBy?: Id | null }): Promise<TopicRec | 'conflict'>;
  getTopic(id: Id): Promise<TopicRec | null>;
  getTopicByKey(key: string): Promise<TopicRec | null>;
  updateTopic(id: Id, patch: TopicPatch, expectedVersion: number | null): Promise<WriteResult<TopicRec>>;
  listTopics(filter: TopicFilter, page: PageReq): Promise<PageRes<TopicRec>>;

  createTopicVersion(v: TopicVersionRec): Promise<TopicVersionRec | 'conflict'>;
  getTopicVersion(id: Id): Promise<TopicVersionRec | null>;
  getTopicVersionBySemver(topicId: Id, version: string): Promise<TopicVersionRec | null>;
  listTopicVersions(topicId: Id): Promise<TopicVersionRec[]>;
  updateTopicVersion(id: Id, patch: Partial<Pick<TopicVersionRec, 'reviewState' | 'doc'>>): Promise<TopicVersionRec | null>;
  /** Topic versions (any state) whose doc references the concept key. */
  topicsUsingConcept(conceptKey: string): Promise<string[]>;

  createBuild(b: BuildRec): Promise<void>;
  updateBuild(id: Id, patch: Partial<Omit<BuildRec, 'id'>>): Promise<BuildRec | null>;
  getBuild(id: Id): Promise<BuildRec | null>;
  /** Latest `ready` build for a topic version. */
  readyBuildForVersion(topicVersionId: Id): Promise<BuildRec | null>;
  listBuilds(filter: { topicKey?: string; status?: BuildStatus }, page: PageReq, order?: 'asc' | 'desc'): Promise<PageRes<BuildRec>>;
  /** Published topics with their ready build (catalog source). */
  listPublished(): Promise<PublishedRec[]>;

  createAsset(a: Omit<AssetRec, 'version'> & { version?: number }): Promise<void>;
  getAsset(id: Id): Promise<AssetRec | null>;
  updateAsset(id: Id, patch: Partial<Omit<AssetRec, 'id'>>): Promise<AssetRec | null>;
  listAssets(page: PageReq): Promise<PageRes<AssetRec>>;
  /** Removes the asset and its versions. */
  deleteAsset(id: Id): Promise<boolean>;
  /** Returns 'conflict' when (assetId, version) exists. */
  createAssetVersion(v: AssetVersionRec): Promise<AssetVersionRec | 'conflict'>;
  /** Ascending by version. */
  listAssetVersions(assetId: Id): Promise<AssetVersionRec[]>;
  updateAssetVersion(assetId: Id, version: number, patch: Partial<Omit<AssetVersionRec, 'assetId' | 'version'>>): Promise<AssetVersionRec | null>;

  listStrings(filter: StringFilter, page: PageReq): Promise<PageRes<LocaleStringRec>>;
  getStrings(keys: readonly string[]): Promise<LocaleStringRec[]>;
  /** Insert or replace; every write bumps the row `version`. */
  upsertStrings(rows: readonly LocaleStringWrite[]): Promise<void>;

  createReviewComment(c: ReviewCommentWrite): Promise<void>;
  getReviewComment(id: Id): Promise<ReviewCommentRec | null>;
  /** Ascending by id (creation order). */
  listReviewComments(filter: ReviewCommentFilter, page: PageReq): Promise<PageRes<ReviewCommentRec>>;
  updateReviewComment(id: Id, patch: Partial<Pick<ReviewCommentRec, 'body' | 'resolvedAt' | 'resolvedBy'>>): Promise<ReviewCommentRec | null>;

  // learning
  getProgress(userId: Id, topicKey: string): Promise<ProgressRec | null>;
  putProgress(p: ProgressRec): Promise<void>;

  createAssignment(a: AssignmentRec): Promise<void>;
  getAssignment(id: Id): Promise<AssignmentRec | null>;
  listAssignments(filter: { classIds: Id[] }, page: PageReq): Promise<PageRes<AssignmentRec>>;

  /** Returns 'conflict' when (userId, clientId) already exists. */
  createAttempt(a: AttemptRec): Promise<AttemptRec | 'conflict'>;
  getAttempt(id: Id): Promise<AttemptRec | null>;
  getAttemptByClientId(userId: Id, clientId: Id): Promise<AttemptRec | null>;
  updateAttempt(id: Id, patch: Partial<Pick<AttemptRec, 'finishedAt' | 'score'>>): Promise<AttemptRec | null>;
  listAttempts(filter: AttemptFilter): Promise<AttemptRec[]>;

  /** Returns 'conflict' when the item was already answered in that attempt. */
  createAnswer(a: AnswerRec): Promise<AnswerRec | 'conflict'>;
  listAnswers(filter: { attemptIds?: Id[]; itemKey?: string }): Promise<AnswerRec[]>;

  /** Insert events; ids already stored are counted as duplicates. */
  insertEvents(events: readonly LearningEventRec[]): Promise<{ accepted: number; duplicates: number }>;
  listEvents(filter: { from?: Date; to?: Date }): Promise<LearningEventRec[]>;

  getIdempotency(userId: Id, key: string): Promise<IdempotencyRec | null>;
  /** Returns false when the key already exists (lost race). */
  putIdempotency(r: IdempotencyRec): Promise<boolean>;

  // decks
  createPresentation(p: PresentationRec): Promise<void>;
  getPresentation(id: Id): Promise<PresentationRec | null>;
  updatePresentation(id: Id, patch: Partial<Pick<PresentationRec, 'title' | 'slides'>>, expectedVersion: number): Promise<WriteResult<PresentationRec>>;
  deletePresentation(id: Id): Promise<boolean>;
  listPresentations(ownerId: Id, page: PageReq): Promise<PageRes<PresentationRec>>;
  createSnapshot(s: SnapshotRec): Promise<void>;
  getSnapshot(id: Id): Promise<SnapshotRec | null>;
  getSnapshots(ids: readonly Id[]): Promise<SnapshotRec[]>;

  // КТП → lesson plans (v0.5.0)
  createTeachingPlan(p: TeachingPlanRec): Promise<void>;
  getTeachingPlan(id: Id): Promise<TeachingPlanRec | null>;
  updateTeachingPlan(id: Id, patch: Partial<Pick<TeachingPlanRec, 'title' | 'doc'>>, expectedVersion: number): Promise<WriteResult<TeachingPlanRec>>;
  /** Delete when the version matches (optimistic lock, like updates). */
  deleteTeachingPlan(id: Id, expectedVersion: number): Promise<'ok' | 'not_found' | 'version_mismatch'>;
  /** Owner's plans ordered by id. */
  listTeachingPlans(ownerId: Id, page: PageReq): Promise<PageRes<TeachingPlanRec>>;

  // tutor
  createThread(t: TutorThreadRec): Promise<void>;
  getThread(id: Id): Promise<TutorThreadRec | null>;
  addTutorMessage(m: TutorMessageRec): Promise<void>;
  listTutorMessages(filter: { threadId?: Id; from?: Date; to?: Date; limit?: number }): Promise<TutorMessageRec[]>;
  // generated content (v0.4.0)
  addGenerated(rows: GeneratedRec[]): Promise<void>;
  getGenerated(id: Id): Promise<GeneratedRec | null>;
  /** Ordered by id (creation order). */
  listGenerated(filter: GeneratedFilter, page: PageReq): Promise<PageRes<GeneratedRec>>;
  updateGenerated(id: Id, patch: Partial<Pick<GeneratedRec, 'status' | 'reviewedAt' | 'reviewedBy' | 'promotedTo'>>): Promise<GeneratedRec | null>;
  /** Atomic counters: times served, «хороший пример», reports (per reason). */
  countGenerated(ids: Id[], delta: { served?: number; good?: number; bad?: number; reason?: string }): Promise<void>;

  // audit & settings
  /** Legacy shape: written to the journal (AuditEvent) since v0.8.0. */
  appendAudit(a: AuditRec): Promise<void>;
  /** Legacy shape: the journal projected to AuditRec, ascending by id. */
  listAudit(filter: AuditFilter, page: PageReq): Promise<PageRes<AuditRec>>;

  // v0.8.0: the action journal (append-only, hash-chained)
  /** Appends one event at the end of the chain (writers are serialised). */
  appendJournal(e: AuditEventInput): Promise<AuditEventRec>;
  /** Newest first (`desc`, the default) or oldest first; the cursor is the last `seq`. */
  listJournal(filter: JournalFilter, page: PageReq, order?: 'asc' | 'desc'): Promise<PageRes<AuditEventRec>>;
  /** Walks the chain: seq without gaps, prevHash links, every hash recomputed. */
  verifyJournal(): Promise<JournalVerifyResult>;
  /** Monthly partitions ahead; drops partitions older than the retention (memory: drops the rows). */
  maintainJournal(now: Date, aheadMonths: number, retainMonths: number): Promise<{ created: number; dropped: number }>;
  /** 'conflict' when an alert with the same key exists. */
  createAlert(a: AuditAlertRec): Promise<AuditAlertRec | 'conflict'>;
  /** Newest first. */
  listAlerts(limit: number): Promise<AuditAlertRec[]>;
  markAlertSeen(id: Id, at: Date): Promise<boolean>;

  // v0.8.0: staff
  getStaffProfile(userId: Id): Promise<StaffProfileRec | null>;
  /** Insert or replace. */
  putStaffProfile(p: StaffProfileRec): Promise<void>;
  listStaffProfiles(): Promise<StaffProfileRec[]>;
  /** Ids of users holding a grant with this role (any scope), ascending. */
  listUserIdsByRole(role: Role): Promise<Id[]>;

  // v0.8.0: support sessions
  createSupportSession(s: SupportSessionRec): Promise<void>;
  getSupportSession(id: Id): Promise<SupportSessionRec | null>;
  /** Ends an open session; null when unknown or already ended. */
  endSupportSession(id: Id, at: Date, by: Id | null, reason: 'ended' | 'expired'): Promise<SupportSessionRec | null>;
  /** Open sessions whose expiry is at or before `now`. */
  listExpiredSupportSessions(now: Date): Promise<SupportSessionRec[]>;

  // v0.8.0: deletion requests
  createDeletionRequest(r: DeletionRequestRec): Promise<void>;
  getDeletionRequest(id: Id): Promise<DeletionRequestRec | null>;
  /** Newest first; the cursor is the last id. */
  listDeletionRequests(filter: { status?: DeletionStatus; requestedBy?: Id }, page: PageReq): Promise<PageRes<DeletionRequestRec>>;
  /** Decides a pending request; null when unknown or no longer pending. */
  decideDeletionRequest(id: Id, d: Pick<DeletionRequestRec, 'status' | 'decidedBy' | 'decidedAt' | 'decisionNote'>): Promise<DeletionRequestRec | null>;
  getSetting(key: string): Promise<SettingRec | null>;
  /** expectedVersion null = upsert without check (defaults/seed). */
  putSetting(key: string, value: unknown, expectedVersion: number | null): Promise<WriteResult<SettingRec>>;

  /** Physically erase soft-deleted users/classes older than `before` (TZ §6: 30 days). */
  purgeDeleted(before: Date): Promise<{ users: number; classes: number }>;
}
